// ═══ BUG: shared SimpleDateFormat ═══
static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");

// Thread-1: sdf.format(date1)  → writes to internal calendar
// Thread-2: sdf.format(date2)  → OVERWRITES the same calendar!
// Result: garbled date, NumberFormatException, or wrong date!

// ═══ FIX 1: new instance per call (safe but slow) ═══
String formatted = new SimpleDateFormat("yyyy-MM-dd").format(date);
// Creates a new object every call → GC pressure at high throughput

// ═══ FIX 2: ThreadLocal (one per thread, reused) ═══
static final ThreadLocal<SimpleDateFormat> dateFormatter =
    ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

String formatted2 = dateFormatter.get().format(date);
// Each thread has its OWN SimpleDateFormat → no sharing → safe!
// Remember: dateFormatter.remove() in finally in thread pools!

// ═══ FIX 3: DateTimeFormatter (BEST — immutable, thread-safe) ═══
static final DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");

String formatted3 = LocalDate.now().format(formatter);
// DateTimeFormatter is IMMUTABLE → share freely! No ThreadLocal needed!
// ONE static final instance for the entire application!

// ═══ WHY SimpleDateFormat is not thread-safe (internal state) ═══
// SimpleDateFormat.format(Date):
//   calendar.setTime(date);     ← writes to SHARED mutable Calendar!
//   subFormat(...)               ← reads from Calendar while another thread writes!
// Two threads → Calendar contains mixed data → wrong output!

// ═══ java.time equivalents ═══
// SimpleDateFormat("yyyy-MM-dd")   → DateTimeFormatter.ofPattern("yyyy-MM-dd")
// sdf.format(new Date())           → LocalDate.now().format(formatter)
// sdf.parse("2024-10-18")          → LocalDate.parse("2024-10-18", formatter)
// Date                              → LocalDate / LocalDateTime / ZonedDateTime
// Calendar                          → LocalDate / LocalDateTime (immutable!)
