// ─── File: src/test/java/com/bank/dateformat/DateFormatSafetyTest.java ───
package com.bank.dateformat;

import org.junit.jupiter.api.Test;
import java.text.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class DateFormatSafetyTest {

    // ═══ BUG: shared SimpleDateFormat produces wrong results ═══
    @Test
    void sharedSimpleDateFormat_producesErrors() throws InterruptedException {
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        AtomicInteger errors = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                try {
                    for (int i = 0; i < 100; i++) {
                        String result = sdf.format(new Date());
                        // Check if result is valid date format
                        if (!result.matches("\\d{4}-\\d{2}-\\d{2}")) {
                            errors.incrementAndGet();
                        }
                    }
                } catch (Exception e) {
                    errors.incrementAndGet();  // NumberFormatException, ArrayIndexOutOfBounds
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        System.out.println("Errors with shared SimpleDateFormat: " + errors.get());
        // Often > 0 — garbled dates or exceptions!
    }

    // ═══ FIX 1: ThreadLocal<SimpleDateFormat> ═══
    static final ThreadLocal<SimpleDateFormat> tlFormatter =
        ThreadLocal.withInitial(() -> new SimpleDateFormat("yyyy-MM-dd"));

    @Test
    void threadLocal_noErrors() throws InterruptedException {
        AtomicInteger errors = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                try {
                    for (int i = 0; i < 100; i++) {
                        String result = tlFormatter.get().format(new Date());
                        if (!result.matches("\\d{4}-\\d{2}-\\d{2}")) errors.incrementAndGet();
                    }
                } finally {
                    tlFormatter.remove();  // cleanup in thread pool!
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(errors.get()).isEqualTo(0);  // zero errors!
    }

    // ═══ FIX 2 (BEST): DateTimeFormatter — immutable, static final ═══
    static final DateTimeFormatter DTF = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    @Test
    void dateTimeFormatter_immutableThreadSafe() throws InterruptedException {
        AtomicInteger errors = new AtomicInteger(0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < 100; i++) {
                    String result = LocalDate.now().format(DTF);
                    if (!result.matches("\\d{4}-\\d{2}-\\d{2}")) errors.incrementAndGet();
                }
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(errors.get()).isEqualTo(0);  // zero errors! No ThreadLocal needed!
    }

    // ═══ DateTimeFormatter parsing ═══
    @Test
    void dateTimeFormatter_parsing() {
        LocalDate date = LocalDate.parse("2024-10-18", DTF);
        assertThat(date.getYear()).isEqualTo(2024);
        assertThat(date.getMonthValue()).isEqualTo(10);
        assertThat(date.getDayOfMonth()).isEqualTo(18);
    }
}
